"""
    Parse the Tab Separated Line to return
    the sentence coloumn.
    """
def get_sentence(line: str, column_number: int) -> str {
    sentence_list = line.split('\t');
    sentence_column = sentence_list[1];
    sentence = sentence_column[:-1];
    return sentence;
}

